function createCoalescingAsyncCache(fetchFn) {
  const cache = new Map();

  return {
    async get(key) {
      if (cache.has(key)) {
        return cache.get(key);
      }
      const data = await fetchFn(key);
      cache.set(key, data);
      return data;
    }
  };
}

module.exports = { createCoalescingAsyncCache };

problems.solutionCode:
function createCoalescingAsyncCache(fetchFn) {
  const cache = new Map();
  const inFlight = new Map();

  return {
    async get(key) {
      if (cache.has(key)) {
        return cache.get(key);
      }
      if (inFlight.has(key)) {
        return inFlight.get(key);
      }

      const promise = Promise.resolve()
        .then(() => fetchFn(key))
        .then((data) => {
          cache.set(key, data);
          return data;
        })
        .finally(() => {
          inFlight.delete(key);
        });

      inFlight.set(key, promise);
      return promise;
    }
  };
}

module.exports = { createCoalescingAsyncCache };

