problems.solutionCode:
function createCircuitBreaker(asyncOperation, options = {}) {
  const failureThreshold = options.failureThreshold !== undefined ? options.failureThreshold : 3;
  const resetTimeoutMs = options.resetTimeoutMs !== undefined ? options.resetTimeoutMs : 50;
  const now = options.now || Date.now;

  let state = 'CLOSED';
  let failureCount = 0;
  let openedAt = 0;
  let probing = false;

  return {
    async execute(...args) {
      const currentTime = now();

      if (state === 'OPEN') {
        if (currentTime - openedAt >= resetTimeoutMs) {
          state = 'HALF_OPEN';
        } else {
          throw new Error('CIRCUIT_BREAKER_OPEN');
        }
      }

      if (state === 'HALF_OPEN') {
        if (probing) {
          throw new Error('CIRCUIT_BREAKER_OPEN');
        }
        probing = true;
      }

      try {
        const result = await asyncOperation(...args);
        state = 'CLOSED';
        failureCount = 0;
        probing = false;
        return result;
      } catch (err) {
        failureCount++;
        if (state === 'HALF_OPEN' || failureCount >= failureThreshold) {
          state = 'OPEN';
          openedAt = now();
        }
        probing = false;
        throw err;
      }
    },
    getState() {
      if (state === 'OPEN' && now() - openedAt >= resetTimeoutMs) {
        return 'HALF_OPEN';
      }
      return state;
    }
  };
}

module.exports = { createCircuitBreaker };

visibleTests.testCode:
let failures = 0;
const flakyClearingHouse = async () => {
  failures++;
  throw new Error('Clearing house gateway error');
};

let fakeTime = 1000;
const breaker = createCircuitBreaker(flakyClearingHouse, { failureThreshold: 3, resetTimeoutMs: 40, now: () => fakeTime });

for (let i = 0; i < 3; i++) {
  await assert.rejects(async () => breaker.execute(), /Clearing house gateway error/);
}

assert.strictEqual(breaker.getState(), 'OPEN');
await assert.rejects(async () => breaker.execute(), /CIRCUIT_BREAKER_OPEN/);
assert.strictEqual(failures, 3);

let calls = 0;
const unstableGateway = async () => {
  calls++;
  if (calls === 1 || calls === 3) throw new Error('Transient error');
  return 'SUCCESS';
};

let fakeTime = 1000;
const breaker = createCircuitBreaker(unstableGateway, { failureThreshold: 2, now: () => fakeTime });

await assert.rejects(async () => breaker.execute(), /Transient error/);
assert.strictEqual(breaker.getState(), 'CLOSED');

const res = await breaker.execute();
assert.strictEqual(res, 'SUCCESS');
assert.strictEqual(breaker.getState(), 'CLOSED');

await assert.rejects(async () => breaker.execute(), /Transient error/);
assert.strictEqual(breaker.getState(), 'CLOSED');

